// Release signing reads keystore.properties (git-ignored, generated by the admin
// panel) and falls back to GitHub Actions environment secrets.
val keystorePropsFile = rootProject.file("keystore.properties")
val keystoreProps = java.util.Properties().apply {
    if (keystorePropsFile.exists()) keystorePropsFile.inputStream().use { load(it) }
}

fun signingValue(key: String, envName: String): String? =
    keystoreProps.getProperty(key) ?: System.getenv(envName)

val keystorePath: String? = signingValue("storeFile", "KEYSTORE_PATH")
val keystoreType: String = signingValue("storeType", "KEYSTORE_TYPE") ?: "PKCS12"

